function loadSettings() {
  document.getElementById("provider_select").value =
    localStorage.getItem("exai_provider") || "auto";

  document.getElementById("gemini_key_input").value =
    localStorage.getItem(PROVIDERS.gemini.storageKey) || "";

  document.getElementById("groq_key_input").value =
    localStorage.getItem(PROVIDERS.groq.storageKey) || "";

  document.getElementById("openrouter_key_input").value =
    localStorage.getItem(PROVIDERS.openrouter.storageKey) || "";

  document.getElementById("custom_model_input").value =
    localStorage.getItem("exai_custom_model") || "";

  updateProviderUI();

  const savedModel = localStorage.getItem("exai_model");
  const modelSelect = document.getElementById("model_select");
  if (savedModel) {
    for (let i = 0; i < modelSelect.options.length; i++) {
      if (modelSelect.options[i].value === savedModel) {
        modelSelect.value = savedModel;
        break;
      }
    }
  }
}

function saveSettings() {
  localStorage.setItem("exai_provider", document.getElementById("provider_select").value);
  localStorage.setItem(PROVIDERS.gemini.storageKey, document.getElementById("gemini_key_input").value.trim());
  localStorage.setItem(PROVIDERS.groq.storageKey, document.getElementById("groq_key_input").value.trim());
  localStorage.setItem(PROVIDERS.openrouter.storageKey, document.getElementById("openrouter_key_input").value.trim());
  localStorage.setItem("exai_model", document.getElementById("model_select").value);
  localStorage.setItem("exai_custom_model", document.getElementById("custom_model_input").value.trim());
}

function updateProviderUI() {
  const provider = document.getElementById("provider_select").value;

  document.getElementById("gemini_key_box").style.display =
    provider === "auto" || provider === "gemini" ? "block" : "none";

  document.getElementById("groq_key_box").style.display =
    provider === "auto" || provider === "groq" ? "block" : "none";

  document.getElementById("openrouter_key_box").style.display =
    provider === "auto" || provider === "openrouter" ? "block" : "none";

  const modelSelect = document.getElementById("model_select");
  modelSelect.innerHTML = "";

  if (provider === "auto") {
    const opt = document.createElement("option");
    opt.value = "auto";
    opt.textContent = "Auto - dùng model mặc định miễn phí của từng provider";
    modelSelect.appendChild(opt);
    modelSelect.disabled = true;
  } else {
    modelSelect.disabled = false;

    for (const item of PROVIDERS[provider].models) {
      const opt = document.createElement("option");
      opt.value = item[0];
      opt.textContent = item[1];
      modelSelect.appendChild(opt);
    }

    modelSelect.value = PROVIDERS[provider].defaultModel;
  }
}

function setStatus(msg, type) {
  const el = document.getElementById("status_area");
  el.className = "status " + type;
  el.innerText = msg;
}

function getKey(provider) {
  if (provider === "gemini") {
    return document.getElementById("gemini_key_input").value.trim();
  }

  if (provider === "groq") {
    return document.getElementById("groq_key_input").value.trim();
  }

  if (provider === "openrouter") {
    return document.getElementById("openrouter_key_input").value.trim();
  }

  return "";
}

function getModelForProvider(provider) {
  const custom = document.getElementById("custom_model_input").value.trim();

  if (custom && document.getElementById("provider_select").value !== "auto") {
    return custom;
  }

  if (document.getElementById("provider_select").value === provider) {
    const model = document.getElementById("model_select").value;
    if (model && model !== "auto") return model;
  }

  return PROVIDERS[provider].defaultModel;
}

// ==================== GỌI AI CHUNG ====================
async function callAI(prompt, options = {}) {
  const selectedProvider = document.getElementById("provider_select").value;

  if (selectedProvider === "auto") {
    const order = ["gemini", "groq", "openrouter"];
    const errors = [];

    for (const provider of order) {
      const key = getKey(provider);
      if (!key) continue;

      try {
        setStatus(`🤖 Đang gọi ${PROVIDERS[provider].label}...`, "loading");
        return await callProvider(provider, key, prompt, options);
      } catch (e) {
        errors.push(`${PROVIDERS[provider].label}: ${e.message}`);
        console.warn(`${provider} lỗi:`, e);
      }
    }

    if (errors.length === 0) {
      throw new Error("Bạn chưa nhập API key Gemini, Groq hoặc OpenRouter.");
    }

    throw new Error("Tất cả provider đều lỗi:\n" + errors.join("\n"));
  }

  const key = getKey(selectedProvider);

  if (!key) {
    throw new Error(`Bạn chưa nhập API key cho ${PROVIDERS[selectedProvider].label}.`);
  }

  return await callProvider(selectedProvider, key, prompt, options);
}

async function callProvider(provider, apiKey, prompt, options = {}) {
  if (provider === "gemini") {
    return await callGemini(apiKey, prompt, options);
  }

  if (provider === "groq") {
    return await callOpenAICompatible({
      provider,
      apiKey,
      apiUrl: "https://api.groq.com/openai/v1/chat/completions",
      model: getModelForProvider(provider),
      prompt,
      options,
    });
  }

  if (provider === "openrouter") {
    return await callOpenAICompatible({
      provider,
      apiKey,
      apiUrl: "https://openrouter.ai/api/v1/chat/completions",
      model: getModelForProvider(provider),
      prompt,
      options,
    });
  }

  throw new Error("Provider không hợp lệ.");
}

async function callGemini(apiKey, prompt, options = {}) {
  const model = getModelForProvider("gemini");
  const system =
    options.system ||
    "Bạn là trợ lý AI tiếng Việt giỏi Excel, Word và Office.js. Trả lời chính xác, ngắn gọn, hữu ích.";

  const fullPrompt = `${system}\n\n${prompt}`;

  const response = await fetch(
    `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent?key=${apiKey}`,
    {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        contents: [
          {
            role: "user",
            parts: [{ text: fullPrompt }],
          },
        ],
        generationConfig: {
          temperature: options.temperature ?? 0.2,
          maxOutputTokens: options.maxTokens || 8192,
          topP: 0.9,
        },
      }),
    }
  );

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw new Error(data.error?.message || "Gemini API lỗi HTTP " + response.status);
  }

  const parts = data.candidates?.[0]?.content?.parts || [];
  const text = parts.map((p) => p.text || "").join("").trim();

  if (!text) {
    throw new Error("Gemini không trả về nội dung.");
  }

  return text;
}

async function callOpenAICompatible({ provider, apiKey, apiUrl, model, prompt, options }) {
  const system =
    options.system ||
    "Bạn là trợ lý AI tiếng Việt giỏi Excel, Word và Office.js. Trả lời chính xác, ngắn gọn, hữu ích.";

  const headers = {
    "Content-Type": "application/json",
    Authorization: "Bearer " + apiKey,
  };

  if (provider === "openrouter") {
    headers["HTTP-Referer"] = "https://duongdinhdbp.github.io/EXAI/";
    headers["X-Title"] = "EXAI Free AI";
  }

  const response = await fetch(apiUrl, {
    method: "POST",
    headers,
    body: JSON.stringify({
      model,
      messages: [
        { role: "system", content: system },
        { role: "user", content: prompt },
      ],
      temperature: options.temperature ?? 0.2,
      max_tokens: options.maxTokens || 8192,
    }),
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw new Error(
      data.error?.message ||
      data.message ||
      `${PROVIDERS[provider].label} API lỗi HTTP ${response.status}`
    );
  }

  const text = data.choices?.[0]?.message?.content;

  if (!text) {
    throw new Error(`${PROVIDERS[provider].label} không trả về nội dung.`);
  }

  return text.trim();
}

// ==================== TIỆN ÍCH CODE ====================
function cleanCode(code) {
  if (!code) return "";

  code = code
    .replace(/```javascript/gi, "")
    .replace(/```js/gi, "")
    .replace(/```/g, "")
    .trim();

  code = code.replace(
    /^[\s\S]*?await\s+(Excel|Word)\.run\s*\(\s*async\s*\([^)]*\)\s*=>\s*\{/i,
    ""
  );

  code = code.replace(
    /await\s+context\.sync\(\)\s*;?\s*\}\s*\)\s*;?\s*$/i,
    ""
  );

  return code.trim();
}

function colToLetter(n) {
  let s = "";
  n = n + 1;

  while (n > 0) {
    const m = (n - 1) % 26;
    s = String.fromCharCode(65 + m) + s;
    n = Math.floor((n - 1) / 26);
  }

  return s;
}

// ==================== ẢNH TỪ URL ====================
function blobToPngBase64(blob) {
  return new Promise((resolve, reject) => {
    const objUrl = URL.createObjectURL(blob);
    const img = new Image();
    img.crossOrigin = "anonymous";

    img.onload = () => {
      try {
        const canvas = document.createElement("canvas");
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;

        const ctx = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0);

        const dataUrl = canvas.toDataURL("image/png");
        URL.revokeObjectURL(objUrl);

        resolve(dataUrl.split(",")[1]);
      } catch (e) {
        URL.revokeObjectURL(objUrl);
        reject(e);
      }
    };

    img.onerror = () => {
      URL.revokeObjectURL(objUrl);
      reject(new Error("Không đọc được ảnh."));
    };

    img.src = objUrl;
  });
}

async function insertBase64ToCell(base64, targetCell, fitCell) {
  const clean = base64.replace(/\s/g, "");

  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const image = sheet.shapes.addImage(clean);

    image.load("width, height");
    await context.sync();

    const cell = sheet.getRange(targetCell);
    cell.load("left, top, width, height");
    await context.sync();

    image.left = cell.left;
    image.top = cell.top;

    if (fitCell) {
      image.width = cell.width;
      image.height = cell.height;
    } else if (image.width > 350) {
      const ratio = 350 / image.width;
      image.width = 350;
      image.height = image.height * ratio;
    }

    await context.sync();
  });
}

async function urlToBase64(url) {
  let lastErr = "";

  for (let i = 0; i < CORS_PROXIES.length; i++) {
    const proxyUrl = CORS_PROXIES[i](url);

    try {
      setStatus(`🖼️ Đang tải ảnh, nguồn ${i + 1}/${CORS_PROXIES.length}...`, "loading");

      const response = await fetch(proxyUrl, { method: "GET" });

      if (!response.ok) {
        lastErr = "HTTP " + response.status;
        continue;
      }

      const blob = await response.blob();

      if (blob.size < 100) {
        lastErr = "Ảnh rỗng hoặc không hợp lệ.";
        continue;
      }

      const pngBase64 = await blobToPngBase64(blob);

      if (pngBase64 && pngBase64.length > 100) {
        return pngBase64;
      }

      lastErr = "Convert PNG thất bại.";
    } catch (e) {
      lastErr = e.message;
      console.warn(`Proxy ${i + 1} lỗi:`, lastErr);
    }
  }

  throw new Error("Đã thử nhiều nguồn nhưng không tải/chèn được ảnh. Lỗi cuối: " + lastErr);
}

async function insertImageFromUrl(imageUrl, targetCell, fitCell) {
  const base64 = await urlToBase64(imageUrl);

  setStatus("📥 Đang chèn ảnh vào Excel...", "loading");

  await insertBase64ToCell(base64, targetCell, fitCell);

  setStatus(`✅ Đã chèn ảnh vào ô ${targetCell}!`, "success");
}

// ==================== PHÂN LOẠI CHAT/ACTION ====================
async function classifyIntent(userPrompt) {
  const p = userPrompt.toLowerCase();

  const actionRegex =
    /(tính|cộng|trừ|nhân|chia|tổng|sum|lọc|filter|sắp xếp|sort|tô màu|đổi màu|định dạng|format|đổi font|xóa|xoá|delete|chèn|insert|ghi vào|điền vào|copy|sao chép|gộp|pivot|đếm|count|thay thế|replace|sửa đoạn|dịch đoạn|viết.*vào|đưa.*vào|tạo bảng|kẻ bảng)/i;

  const chatRegex =
    /(giải thích|là gì|tại sao|vì sao|hướng dẫn|tư vấn|cho biết|kể|phân tích giúp|nói về)/i;

  if (actionRegex.test(p) && !chatRegex.test(p)) {
    return "ACTION";
  }

  const prompt = `Phân loại yêu cầu sau. Chỉ trả về đúng 1 từ: CHAT hoặc ACTION.

ACTION = cần thao tác/thay đổi dữ liệu, công thức, định dạng trong Excel/Word.
CHAT = hỏi đáp, giải thích, tư vấn, không cần sửa file.

Yêu cầu:
${userPrompt}

Trả về CHAT hoặc ACTION:`;

  const result = await callAI(prompt, {
    temperature: 0,
    maxTokens: 20,
    system: "Bạn là bộ phân loại ý định. Chỉ trả về CHAT hoặc ACTION.",
  });

  return result.toUpperCase().includes("ACTION") ? "ACTION" : "CHAT";
}

// ==================== CHAT ====================
async function handleChat(userPrompt) {
  const cellMatch = userPrompt.match(
    /\b(?:vào|ghi vào|điền vào|trả lời vào|ô)\s*([A-Z]{1,3}\d{1,7})\b/i
  );

  const targetCell = cellMatch ? cellMatch[1].toUpperCase() : null;

  const chatPrompt = `Bạn là trợ lý AI thông minh, thân thiện.
Trả lời bằng tiếng Việt rõ ràng, hữu ích.
${targetCell ? "Lưu ý: trả lời ngắn gọn vì sẽ ghi vào một ô Excel." : ""}

Câu hỏi/yêu cầu:
${userPrompt}

Trả lời:`;

  const answer = await callAI(chatPrompt, {
    temperature: 0.3,
  });

  if (targetCell && HOST_APP === "Excel") {
    await Excel.run(async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.getRange(targetCell).values = [[answer]];
      await context.sync();
    });

    setStatus(`✅ Đã trả lời và ghi vào ô ${targetCell}:\n\n${answer}`, "success");
  } else {
    setStatus(`💬 ${answer}`, "success");
  }
}

// ==================== BỐI CẢNH EXCEL ====================
async function getExcelContext() {
  let info = "";

  await Excel.run(async (ctx) => {
    const sel = ctx.workbook.getSelectedRange();
    sel.load("address, rowCount, columnCount, values, columnIndex, rowIndex");

    const sheet = ctx.workbook.worksheets.getActiveWorksheet();
    sheet.load("name");

    await ctx.sync();

    const isMulti = sel.rowCount > 1 || sel.columnCount > 1;
    const selAddr = sel.address.split("!").pop();

    info += `- Sheet: "${sheet.name}"\n`;

    if (isMulti) {
      info += `\n### NGƯỜI DÙNG ĐANG BÔI ĐEN VÙNG: ${selAddr}\n`;
      info += `### Dữ liệu vùng bôi đen đã được đọc sẵn vào biến selData.\n`;
      info += `- Kích thước vùng: ${sel.rowCount} dòng x ${sel.columnCount} cột\n`;
      info += `- Ánh xạ cột:\n`;

      for (let j = 0; j < sel.columnCount; j++) {
        info += `    selData[i][${j}] = cột ${colToLetter(sel.columnIndex + j)}\n`;
      }

      const preview = sel.values
        .slice(0, 25)
        .map((r, i) => `  selData[${i}] = [${r.join(" | ")}]`)
        .join("\n");

      info += `- Nội dung xem trước:\n${preview}\n`;

      if (sel.rowCount > 25) {
        info += `  ...(tổng ${sel.rowCount} dòng)\n`;
      }
    } else {
      info += `- Đang chọn 1 ô: ${selAddr}\n`;

      const used = sheet.getUsedRangeOrNullObject();
      used.load("address, values, rowCount, columnCount");

      await ctx.sync();

      if (!used.isNullObject) {
        info += `- Vùng có dữ liệu: ${used.address} (${used.rowCount} dòng x ${used.columnCount} cột)\n`;

        const preview = used.values
          .slice(0, 20)
          .map((r, i) => `  dòng ${i}: [${r.join(" | ")}]`)
          .join("\n");

        info += `- Dữ liệu xem trước:\n${preview}\n`;
      }
    }
  });

  return info;
}

async function runExcelCode(code) {
  await Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getActiveWorksheet();
    const workbook = context.workbook;

    const sel = workbook.getSelectedRange();
    sel.load("values, rowCount, columnCount, address, columnIndex, rowIndex");

    await context.sync();

    const selData = sel.values;
    const selInfo = {
      address: sel.address,
      rowCount: sel.rowCount,
      colCount: sel.columnCount,
      startCol: sel.columnIndex,
      startRow: sel.rowIndex,
    };

    const runner = new Function(
      "context",
      "sheet",
      "workbook",
      "Excel",
      "selData",
      "selInfo",
      `return (async () => { ${code}\nawait context.sync(); })();`
    );

    await runner(context, sheet, workbook, Excel, selData, selInfo);

    await context.sync();
  });
}

// ==================== BỐI CẢNH WORD ====================
async function getWordContext() {
  let info = "";

  await Word.run(async (ctx) => {
    const sel = ctx.document.getSelection();
    sel.load("text");

    await ctx.sync();

    info += `- Văn bản đang chọn: "${sel.text || "(chưa chọn gì)"}"\n`;
  });

  return info;
}

async function runWordCode(code) {
  await Word.run(async (context) => {
    const doc = context.document;
    const selection = context.document.getSelection();
    const body = context.document.body;

    const runner = new Function(
      "context",
      "doc",
      "selection",
      "body",
      "Word",
      `return (async () => { ${code}\nawait context.sync(); })();`
    );

    await runner(context, doc, selection, body, Word);

    await context.sync();
  });
}

